//! Constant JavaScript the room page carries (crudspec's widgets jump_to_newest and
//! format_messages), byte for byte.

pub const JUMP_SCRIPT: &str = r##"<script>(function(b){var l=document.querySelector(".messages");if(!l||!window.IntersectionObserver)return;var o=new IntersectionObserver(function(e){b.hidden=e[0].isIntersecting});var w=function(){o.disconnect();if(l.lastElementChild)o.observe(l.lastElementChild)};w();new MutationObserver(w).observe(l,{childList:true})})(document.currentScript.previousElementSibling)</script>"##;

pub const FORMAT_SCRIPT: &str = r##"<script>(function(){var day=new Intl.DateTimeFormat(undefined,{dateStyle:"short"});function ts(m){var t=m.querySelector(".message__day-separator time[datetime], .message__day-separator[datetime], time[datetime]");return t?Date.parse(t.getAttribute("datetime")):NaN}function run(){document.querySelectorAll(".messages").forEach(function(l){var prev=null;l.querySelectorAll(":scope > .message, :scope > * > .message").forEach(function(m){var t=ts(m),p=prev&&ts(prev);m.classList.toggle("message--first-of-day",!prev||isNaN(t)||isNaN(p)||day.format(new Date(p))!==day.format(new Date(t)));m.classList.toggle("message--threaded",!!prev&&prev.dataset.userId===m.dataset.userId&&t-p<300000);prev=m;var d=m.querySelector(".message__day-separator time[datetime], .message__day-separator[datetime]");if(d&&!d.dataset.local){d.dataset.local=1;d.textContent=new Date(d.getAttribute("datetime")).toLocaleDateString(undefined,{year:"numeric",month:"long",day:"numeric"})}})})}run();new MutationObserver(run).observe(document.getElementById("message-area")||document.body,{childList:true,subtree:true})})()</script>"##;
